// ItemTypeUpdate 所有字段可选；capabilities 省略表示不修改能力结构。
type ItemTypeUpdate struct {
	Capabilities *[]Capability `json:"capabilities,omitempty"`

	// CapabilitiesVersion 乐观锁版本。修改 `capabilities` 时**必填**（否则 400）；服务端发现已被他人修改时返回 409。
	// UI 保存时总是带上，避免用陈旧的能力数组覆盖别人刚加的能力项。
	CapabilitiesVersion *int     `json:"capabilitiesVersion,omitempty"`
	DefaultDepth        *float64 `json:"defaultDepth,omitempty"`
	DefaultWidth        *float64 `json:"defaultWidth,omitempty"`

	// Driver 省略表示不变；空字符串表示清除
	Driver *string `json:"driver,omitempty"`

	// Icons 图标名（Lucide 命名空间内）；空串与不填等价，表示没有图标
	Icons *string              `json:"icons,omitempty"`
	Mount *ItemTypeUpdateMount `json:"mount,omitempty"`
	Name  *string              `json:"name,omitempty"`
}

// ItemTypeUpdateMount defines model for ItemTypeUpdate.Mount.
type ItemTypeUpdateMount string

// ItemUpdate 只更新出现的字段；roomHash 传空字符串表示移出房间。
type ItemUpdate struct {
	Attrs    *map[string]interface{} `json:"attrs,omitempty"`
	Name     *string                 `json:"name,omitempty"`
	RoomHash *string                 `json:"roomHash,omitempty"`
	Rotation *float64                `json:"rotation,omitempty"`
	Status   *ItemUpdateStatus       `json:"status,omitempty"`

	// WallId 改成挂墙物品；空字符串表示脱离墙面、回到自由摆放。
	// `mount` 为 `wall` 的类型不接受空字符串（400）。
	WallId *string `json:"wallId,omitempty"`

	// WallOffset 与 wallId 一起给出；脱离墙面时忽略
	WallOffset *float64 `json:"wallOffset,omitempty"`
	X          *float64 `json:"x,omitempty"`
	Y          *float64 `json:"y,omitempty"`
}

// ItemUpdateStatus defines model for ItemUpdate.Status.
type ItemUpdateStatus string

// LoginRequest defines model for LoginRequest.
type LoginRequest struct {
	Password string `json:"password"`

	// Username Examples: zhang
	Username string `json:"username"`
}

// Opening defines model for Opening.
type Opening struct {
	Height float64            `json:"height"`
	Id     openapi_types.UUID `json:"id"`
	Kind   OpeningKind        `json:"kind"`

	// Offset 距墙 A 端点的偏移（厘米）
	Offset float64 `json:"offset"`

	// Sill 离地高度（厘米）；门为 0
	Sill   float64            `json:"sill"`
	WallId openapi_types.UUID `json:"wallId"`
	Width  float64            `json:"width"`
}

// OpeningKind defines model for Opening.Kind.
type OpeningKind string

// OpeningInput defines model for OpeningInput.
type OpeningInput struct {
	Height *float64           `json:"height,omitempty"`
	Kind   OpeningInputKind   `json:"kind"`
	Offset float64            `json:"offset"`
	Sill   *float64           `json:"sill,omitempty"`
	WallId openapi_types.UUID `json:"wallId"`
	Width  float64            `json:"width"`
}

// OpeningInputKind defines model for OpeningInput.Kind.
type OpeningInputKind string

// OpeningPatch 只改出现的字段。
type OpeningPatch struct {
	Height *float64 `json:"height,omitempty"`
	Offset *float64 `json:"offset,omitempty"`
	Sill   *float64 `json:"sill,omitempty"`
	Width  *float64 `json:"width,omitempty"`
}

// Plan defines model for Plan.
type Plan struct {
	Corners []Corner `json:"corners"`

	// OpenWalls 没有参与任何闭合区域的墙数；大于 0 时前端提示「还有墙没围上」
	OpenWalls int `json:"openWalls"`

	// Openings 门与窗。和挂墙物品一样用「墙 + 沿墙偏移」定位，
	// 墙移动或改长后偏移不变、世界坐标跟着墙走。
	Openings []Opening `json:"openings"`

	// Rooms 由墙的闭环推导出来的房间。前端只渲染，不自己推导。
	// 墙没围成闭环时这里是空数组，`openWalls` 会给出提示依据。
	Rooms []Room `json:"rooms"`

	// StaleRooms 失配的房间名：墙改过之后，原来那间房的哈希对不上了，名字就悬空在这里。
	// 前端据此提示「原来给客厅起的名字已失效」，并允许一键清理。
	StaleRooms []StaleRoom `json:"staleRooms"`

	// Underlay 垫在画布下面的底图元数据。没有底图时是 `null`。
	// 图片字节不在 JSON 里，走 `GET /api/plan/underlay/image`；
	// 换图、定标、透明度这些改动都不改变户型版本号。
	Underlay *Underlay `json:"underlay,omitempty"`

	// Version 平面图版本号。每次整份替换成功后 +1，撤销/重做靠它做乐观并发：
	// 写回时带上旧版本号，服务端发现对不上就返回 409，客户端重新取全量。
	Version int64  `json:"version"`
	Walls   []Wall `json:"walls"`
}

// PlanInput 整份替换整个户型（撤销/重做用）。
type PlanInput struct {
	// Version 客户端读到的版本号；与服务端不一致时返回 409
	Version int64          `json:"version"`
	Walls   []WallSnapshot `json:"walls"`
}

// PlanPoint defines model for PlanPoint.
type PlanPoint struct {
	X float64 `json:"x"`
	Y float64 `json:"y"`
}

// Room 由墙的闭环推导出来的房间。几何不落库，只把多边形的哈希当作身份：
// 墙一改，哈希就变，挂在旧哈希上的名字自然失配（不会把「客厅」挂到卫生间上）。
type Room struct {
	// AreaM2 面积（平方米，两位小数）
	AreaM2 float64 `json:"areaM2"`

	// Hash 多边形顶点规范化后的哈希，房间命名的键
	Hash string `json:"hash"`

	// Kind 房间用途；还没指定时为空
	Kind *RoomKind `json:"kind,omitempty"`

	// Name 用户起的名字；还没起名时为空
	Name *string `json:"name,omitempty"`

	// Ring 闭合多边形的顶点，首尾不重复
	Ring []PlanPoint `json:"ring"`
}

// RoomKind 房间用途；还没指定时为空
type RoomKind string

// RoomNameInput defines model for RoomNameInput.
type RoomNameInput struct {
	Kind *RoomNameInputKind `json:"kind,omitempty"`

	// Name 房间名，1–24 个字
	Name string `json:"name"`
}

// RoomNameInputKind defines model for RoomNameInput.Kind.
type RoomNameInputKind string

// SessionUser defines model for SessionUser.
type SessionUser struct {
	DisplayName string             `json:"displayName"`
	Id          openapi_types.UUID `json:"id"`
	Role        SessionUserRole    `json:"role"`
	Username    string             `json:"username"`
}

// SessionUserRole defines model for SessionUser.Role.
type SessionUserRole string

// StaleRoom 失配的房间名——哈希已经不属于任何现存房间。
type StaleRoom struct {
	Hash string         `json:"hash"`
	Kind *StaleRoomKind `json:"kind,omitempty"`
	Name string         `json:"name"`
}

// StaleRoomKind defines model for StaleRoom.Kind.
type StaleRoomKind string

// Underlay 底图的元数据。`cmPerPx` 与 `offsetXCm/offsetYCm` 一起定义「图片像素 → 世界厘米」的映射：
// 图片左上角落在 `(offsetXCm, offsetYCm)`，每像素宽 `cmPerPx` 厘米，旋转绕图片中心。
type Underlay struct {
	// CmPerPx 一个像素等于多少厘米；未定标时是上传时按包围盒铺满算出的估计值
	CmPerPx     float64             `json:"cmPerPx"`
	ContentType UnderlayContentType `json:"contentType"`
	HeightPx    int                 `json:"heightPx"`
	OffsetXCm   float64             `json:"offsetXCm"`
	OffsetYCm   float64             `json:"offsetYCm"`
	Opacity     float64             `json:"opacity"`
	RotationDeg UnderlayRotationDeg `json:"rotationDeg"`

	// Sha256 图片字节的摘要，前端可据此判断要不要重新拉图
	Sha256    string    `json:"sha256"`
	UpdatedAt time.Time `json:"updatedAt"`
	Visible   bool      `json:"visible"`
	WidthPx   int       `json:"widthPx"`
}

// UnderlayContentType defines model for Underlay.ContentType.
type UnderlayContentType string

// UnderlayRotationDeg defines model for Underlay.RotationDeg.
type UnderlayRotationDeg int

// UnderlayPatch 只改出现的字段。
type UnderlayPatch struct {
	CmPerPx     *float64                  `json:"cmPerPx,omitempty"`
	OffsetXCm   *float64                  `json:"offsetXCm,omitempty"`
	OffsetYCm   *float64                  `json:"offsetYCm,omitempty"`
	Opacity     *float64                  `json:"opacity,omitempty"`
	RotationDeg *UnderlayPatchRotationDeg `json:"rotationDeg,omitempty"`
	Visible     *bool                     `json:"visible,omitempty"`
}

// UnderlayPatchRotationDeg defines model for UnderlayPatch.RotationDeg.
type UnderlayPatchRotationDeg int

// Wall defines model for Wall.
type Wall struct {
	// AId 起点端点 id
	AId openapi_types.UUID `json:"aId"`

	// ArcExtent 弧度（度），0 为直墙
	ArcExtent float64            `json:"arcExtent"`
	Ax        float64            `json:"ax"`
	Ay        float64            `json:"ay"`
	BId       openapi_types.UUID `json:"bId"`
	Bx        float64            `json:"bx"`
	By        float64            `json:"by"`
	Id        openapi_types.UUID `json:"id"`
	Thickness float64            `json:"thickness"`
}

// WallInput defines model for WallInput.
type WallInput struct {
	// ArcExtent 弧度（度）。0 表示直墙；正负表示往弦的哪一侧弯（逆时针为正）。
	// 半径与圆心由弦长和弧角反解，不落库。
	ArcExtent *float64 `json:"arcExtent,omitempty"`

	// Ax 起点 x，单位厘米，原点在平面图左上角（0–5000，超出会被拒）
	Ax float64 `json:"ax"`
	Ay float64 `json:"ay"`

	// Bx 终点 x（0–5000，超出会被拒）
	Bx float64 `json:"bx"`
	By float64 `json:"by"`

	// Thickness 墙厚（厘米），省略时为 10
	Thickness *float64 `json:"thickness,omitempty"`
}

// WallSnapshot 整份替换时的一面墙。`id` 可省略：省略表示新建（服务端生成），
// 带上表示「这面墙原来就在」——撤销/重做必须保住 id，否则门窗的
// `wall_id` 与前端选中态都会断。
type WallSnapshot struct {
	// ArcExtent 弧度（度），0 为直墙
	ArcExtent *float64            `json:"arcExtent,omitempty"`
	Ax        float64             `json:"ax"`
	Ay        float64             `json:"ay"`
	Bx        float64             `json:"bx"`
	By        float64             `json:"by"`
	Id        *openapi_types.UUID `json:"id,omitempty"`
	Thickness *float64            `json:"thickness,omitempty"`
}

