// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Login 用账号密码换取会话 Cookie
	// (POST /api/auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout 清除会话
	// (POST /api/auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// Me 取当前会话的用户
	// (GET /api/auth/me)
	Me(w http.ResponseWriter, r *http.Request)
	// ListCommandLogs 按时间倒序列出最近操作记录
	// (GET /api/command-logs)
	ListCommandLogs(w http.ResponseWriter, r *http.Request, params ListCommandLogsParams)
	// Healthz 健康检查
	// (GET /api/healthz)
	Healthz(w http.ResponseWriter, r *http.Request)
	// ListItemTypes 列出全部类型模板
	// (GET /api/item-types)
	ListItemTypes(w http.ResponseWriter, r *http.Request)
	// CreateItemType 新建类型模板（仅管理员）
	// (POST /api/item-types)
	CreateItemType(w http.ResponseWriter, r *http.Request)
	// DeleteItemType 删除类型模板（仅管理员）
	// (DELETE /api/item-types/{key})
	DeleteItemType(w http.ResponseWriter, r *http.Request, key string)
	// UpdateItemType 修改类型模板（仅管理员）
	// (PATCH /api/item-types/{key})
	UpdateItemType(w http.ResponseWriter, r *http.Request, key string)
	// ListItems 列出物品（可按房间、类别、关键字筛选）
	// (GET /api/items)
	ListItems(w http.ResponseWriter, r *http.Request, params ListItemsParams)
	// CreateItem 新建物品（家具或设备）
	// (POST /api/items)
	CreateItem(w http.ResponseWriter, r *http.Request)
	// DeleteItem 删除物品
	// (DELETE /api/items/{id})
	DeleteItem(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// UpdateItem 修改物品名称、房间、坐标、旋转或装饰属性
	// (PATCH /api/items/{id})
	UpdateItem(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// SendItemCommand 给设备下发一条能力命令
	// (POST /api/items/{id}/commands)
	SendItemCommand(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// ListItemStates 读取物品当前能力状态
	// (GET /api/items/{id}/states)
	ListItemStates(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// CreateOpening 在墙上开一个门或窗
	// (POST /api/openings)
	CreateOpening(w http.ResponseWriter, r *http.Request)
	// DeleteOpening 删掉一个开口
	// (DELETE /api/openings/{openingId})
	DeleteOpening(w http.ResponseWriter, r *http.Request, openingId openapi_types.UUID)
	// UpdateOpening 调整开口的位置或尺寸
	// (PATCH /api/openings/{openingId})
	UpdateOpening(w http.ResponseWriter, r *http.Request, openingId openapi_types.UUID)
	// GetPlan 取当前户型（端点与墙）
	// (GET /api/plan)
	GetPlan(w http.ResponseWriter, r *http.Request)
	// ReplacePlan 整份替换户型（撤销/重做）
	// (PUT /api/plan)
	ReplacePlan(w http.ResponseWriter, r *http.Request)
	// ClearUnderlay 删除底图（连图片字节）
	// (DELETE /api/plan/underlay)
	ClearUnderlay(w http.ResponseWriter, r *http.Request)
	// UpdateUnderlay 改底图的定标与显示参数
	// (PATCH /api/plan/underlay)
	UpdateUnderlay(w http.ResponseWriter, r *http.Request)
	// UploadUnderlay 上传底图（整张替换）
	// (PUT /api/plan/underlay)
	UploadUnderlay(w http.ResponseWriter, r *http.Request)
	// ClearRoomName 清掉房间名
	// (DELETE /api/rooms/{hash})
	ClearRoomName(w http.ResponseWriter, r *http.Request, hash string)
	// UpdateRoomName 给房间起名或改用途
	// (PATCH /api/rooms/{hash})
	UpdateRoomName(w http.ResponseWriter, r *http.Request, hash string)
	// AdvanceSimulation 推进模拟器指定分钟数
	// (POST /api/sim/tick)
	AdvanceSimulation(w http.ResponseWriter, r *http.Request)
	// CreateWall 画一面墙
	// (POST /api/walls)
	CreateWall(w http.ResponseWriter, r *http.Request)
	// DeleteWall 删除一面墙
	// (DELETE /api/walls/{wallId})
	DeleteWall(w http.ResponseWriter, r *http.Request, wallId openapi_types.UUID)
	// UpdateWall 改一面墙的端点或厚度
	// (PATCH /api/walls/{wallId})
	UpdateWall(w http.ResponseWriter, r *http.Request, wallId openapi_types.UUID)
}

